<template>
   <v-container>
     <div>
            <div v-if="likePosts && likePosts.length > 0">
                <div v-for="post in validPosts" :key="post._id">
            <Post
                 :image="urls + '/static/' + post.post._id + '.PNG'"
                :name="post.post.text || 'مستخدم'"  
                :id="post.post._id"
                :commentsArr="post.post.comments || []"   
                :likeNumber="post.post.likes.length || 0" 
                :likesArr="post.post.likes || []"          
                :owner="post.post.owner"
                :ownerName="post.user.name || 'غير معروف'" 
                :ownerId="post.post.owner._id"
                :date="post.post.date"
                :ref="`post-${post._id}`"
                :isFriend="true"
                @add-remove-like="refresh"
                
            >
            </Post>
            
        </div>
            </div>
            <div v-else>
                <h3>
                    No Liked Posts yet
                </h3>
            </div>
        
    </div>
   </v-container>
</template>

<script>
import axios from 'axios'
import serverUrl from '../../config'
import Post from '../post/post.vue'

export default {
    data() {
        return {
            urls: serverUrl,
            likePosts: null,
            editLike: [],
            tempLike: null
        }
    },
     created() {
       this.fetchLikedPosts()
    },
    mounted() {
        
    },
    computed: {
        validPosts() {
            if (!this.likePosts || !this.likePosts.length) {
                return []
            }
            // تصفية العناصر التي تحتوي على post صحيح
            return this.likePosts.filter(function(post) {
                return post && post.post && post.post._id
            })
        }
    },
    methods: {
        async fetchLikedPosts() {
            let result = await axios.get(serverUrl + '/api/user-activity/likes', {
                headers: { authorization: localStorage.getItem("token") }
            })
            if (result.data.success) {
                this.likePosts = result.data.likes

                 this.emitLikesNumber()
            }
            console.log('likes: ', result.data)
            console.log('validPost', this.validPosts.length)
        },
        refresh(post) {
             console.log('refresh', post)
            const index = this.likePosts.findIndex(item => {
                
                return item.post && item.post._id === post.postID
             })
              console.log('edit post like', this.likePosts)
             console.log('indexyyy', index)
            
            
              
                this.editLike[index] = !this.editLike[index]
            console.log('eeeaa', this.editLike)
            if (this.editLike[index]) {
                console.log('exist')
                const likeArrIndex = this.likePosts[index].post.likes.findIndex(like => {
                    return like.user._id == localStorage.getItem('userID')
                })
                this.tempLike =  this.likePosts[index].post.likes[likeArrIndex]
                this.likePosts[index].post.likes.splice(likeArrIndex, 1)
            } else {
                this.likePosts[index].post.likes.push(this.tempLike)
            }

            this.emitLikesNumber()
        },
         emitLikesNumber() {
            this.$emit('likes-number', 
                 this.validPosts.length,
                
            )
        },
    },
     watch: {
        // ✅ مراقبة التغييرات على likePosts
        likePosts: {
            handler(newVal) {
                if (newVal) {
                    this.emitLikesNumber()
                }
            },
            deep: true
        }
    },
    components: {
        Post
    }
}
</script>

