<template>
 <div style="margin-right:-13px;margin-left: -13px;">
   <v-card class="custom-card">
    <v-tabs
      v-model="tab"
      background-color="#1976D2"
      centered
      color="white"
      icons-and-text
      class="shift"
    >
      <v-tabs-slider color="white"></v-tabs-slider>

      <v-tab href="#tab-1">
        comments {{ totalCommentsNumber ? '(' + totalCommentsNumber + ')' : '' }}
        <v-icon>mdi-comment</v-icon>
      </v-tab>

      <v-tab href="#tab-2">
        likes  {{ totalLikesNumber ? '(' + totalLikesNumber + ')' : ''}}
        <v-icon>mdi-thumb-up</v-icon>
      </v-tab>
    </v-tabs>

    <v-tabs-items v-model="tab">
      <v-tab-item
        v-for="i in 2"
        :key="i"
        :value="'tab-' + i"
      >
        <v-card flat>
          <v-card-text>
            <component :is="currentComponent" @likes-number="handleLikesNumber" @comments-number="handlwCommentsNumber"></component>
          </v-card-text>
        </v-card>
      </v-tab-item>
    </v-tabs-items>
  </v-card>
 </div>
</template>

<script>
import CommentComponent from './comment.vue'
import LikesComponent from './like.vue'

export default {
    data() {
        return {
            tab: null,
            currentComponent: null,
            totalLikesNumber: null,
            totalCommentsNumber: null,
        }
    },
    watch: {
        tab(newTab) {
            if (newTab == 'tab-1') {
                this.currentComponent = 'MyComment'
            } else if (newTab == 'tab-2') {
                this.currentComponent = 'MyLikes'
            }
        }
    },
    methods: {
      handleLikesNumber(d) {
        console.log('likes number is: ', d)
        this.totalLikesNumber = d
    },
    handlwCommentsNumber(c) {
      console.log('Comments number is: ', c)
      this.totalCommentsNumber = c
    }
  },
    created() {
          this.tab = 'tab-1'
        this.currentComponent = 'MyComment'
    },
    components: {
        MyComment: CommentComponent,
        MyLikes: LikesComponent
    }
}
</script>

<style scoped>
.shift {
    margin-top: -25px;
}
.custom-card {
 position: sticky !important;
}
</style>